/// Metadata of the setting with this core key.
#[must_use]
pub fn setting_ui(scope: SettingScope, field: &str) -> Option<&'static SettingUi> {
    SETTING_UI
        .iter()
        .find(|row| row.scope == scope && row.field == field)
}
